-- TAG: UPDATE_SECTION_NAMES_STEP1 update sudstaff.section set name = '2' where name = '1';
-- TAG: UPDATE_SECTION_NAMES_STEP2 update sudstaff.section set name = '1' where name = '1й участок центрального района';
-- TAG: RENAME_COLUMN_NAME_TO_NUMBER ALTER TABLE sudstaff.section RENAME COLUMN name to number;
-- TAG: ALTER_COLUMN_TYPE_TO_INTEGER ALTER TABLE sudstaff.section ALTER COLUMN number type Integer using ( case when number = '1' then 1 when number = '2' then 2 else 1 end );

-- TAG: UPDATE_SECTION_PERSONAL_NUMBER update sudstaff.section set personel_number = '54MS0067' where personel_number = '2';
-- TAG: UPDATE_SECTION_PERSONAL_NUMBER update sudstaff.section set personel_number = '54MS0068' where personel_number = '54MS0000';
-- TAG: UPDATE_SECTION_NUMBER update sudstaff.section set number = '2' where personel_number = '54MS0068';
